class Box { public int Count { get; set; } public string Text { get; set; } = "A"; }
void Main() {
    var b = new Box();
    for (; b.Count < 3; b.Count++) { if (b.Count == 1) continue; Print(b.Count); }
    Print(false && (++b.Count > 0)); Print(true ? b.Count : ++b.Count);
    Print(b.Text += (b.Text = "B")); Print(b.Text);
    b.Count = 2147483647; Print(++b.Count);
}
